package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	root := "/bench/repo"
	fset := token.NewFileSet()
	var decls []string
	var calls []string

	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || !strings.HasSuffix(path, ".go") {
			return nil
		}
		if strings.Contains(path, "/vendor/") {
			return nil
		}
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return nil
		}
		ast.Inspect(f, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.FuncDecl:
				if x.Recv != nil && x.Name.Name == "RunOnce" {
					recv := x.Recv.List[0].Type
					decls = append(decls, fmt.Sprintf("%s:%d: func (%s) RunOnce", path, fset.Position(x.Pos()).Line, formatRecv(recv)))
				}
			case *ast.CallExpr:
				if sel, ok := x.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "RunOnce" {
					calls = append(calls, fmt.Sprintf("%s:%d: %s", path, fset.Position(x.Pos()).Line, formatExpr(sel)))
				}
			}
			return true
		})
		return nil
	})
	if err != nil {
		panic(err)
	}
	fmt.Println("=== DECLARATIONS ===")
	for _, d := range decls {
		fmt.Println(d)
	}
	fmt.Println("=== CALLS ===")
	for _, c := range calls {
		fmt.Println(c)
	}
}

func formatRecv(t ast.Expr) string {
	switch x := t.(type) {
	case *ast.StarExpr:
		if id, ok := x.X.(*ast.Ident); ok {
			return "*"+id.Name
		}
	case *ast.Ident:
		return x.Name
	}
	return "?"
}

func formatExpr(sel *ast.SelectorExpr) string {
	if id, ok := sel.X.(*ast.Ident); ok {
		return id.Name + ".RunOnce"
	}
	return "?.RunOnce"
}
