#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

sub strip_go_source {
    my ($src) = @_;
    my $out = '';
    my $i = 0;
    my $len = length($src);
    while ($i < $len) {
        my $c = substr($src, $i, 1);
        if ($c eq '/' && $i + 1 < $len) {
            my $n = substr($src, $i + 1, 1);
            if ($n eq '/') {
                $i += 2;
                while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
                next;
            }
            if ($n eq '*') {
                $i += 2;
                while ($i + 1 < $len && !(substr($src, $i, 1) eq '*' && substr($src, $i + 1, 1) eq '/')) {
                    $i++;
                }
                $i += 2 if $i + 1 < $len;
                next;
            }
        }
        if ($c eq '"' || $c eq '`') {
            my $quote = $c;
            $out .= $c;
            $i++;
            while ($i < $len) {
                my $ch = substr($src, $i, 1);
                $out .= $ch;
                $i++;
                if ($ch eq '\\' && $i < $len) {
                    $out .= substr($src, $i, 1);
                    $i++;
                    next;
                }
                last if $ch eq $quote;
            }
            next;
        }
        if ($c eq "'" && $i + 2 < $len) {
            $out .= substr($src, $i, 3);
            $i += 3;
            next;
        }
        $out .= $c;
        $i++;
    }
    return $out;
}

sub is_test_file {
    my ($path) = @_;
    return $path =~ /_test\.go$/;
}

sub pkg_path_from_file {
    my ($file) = @_;
    my $dir = dirname($file);
    $dir =~ s/^\Q$REPO\E\/?//;
    return $dir eq '' ? $MODULE : "$MODULE/$dir";
}

my %decls;
my @decl_order;

sub decl_key {
    my ($pkg_path, $recv, $name) = @_;
    $recv //= '';
    return "$pkg_path|$recv|$name";
}

sub parse_internal_decls {
    find({
        wanted => sub {
            return unless $_ =~ /\.go$/;
            return unless $File::Find::name =~ m{^\Q$REPO\E/internal/};
            my $file = $File::Find::name;
            open my $fh, '<', $file or return;
            local $/;
            my $raw = <$fh>;
            close $fh;

            my $pkg = 'unknown';
            if ($raw =~ /^package\s+(\w+)/m) {
                $pkg = $1;
            }
            my $pkg_path = pkg_path_from_file($file);
            my @lines = split /\n/, $raw;
            for my $ln (0 .. $#lines) {
                my $line = $lines[$ln];
                next unless $line =~ /^\s*func\s+/;
                my ($recv, $name);
                if ($line =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
                    ($recv, $name) = ($1, $2);
                    $recv =~ s/^\s+|\s+$//g;
                    if ($recv =~ /\*\s*([\w\.]+)\s*$/) {
                        $recv = $1;
                    } elsif ($recv =~ /([\w\.]+)\s*$/) {
                        $recv = $1;
                    }
                } elsif ($line =~ /^\s*func\s+(\w+)\s*[\(<]/) {
