+        no_chdir => 1,
+    }, "$REPO/internal");
+}
+
+sub parse_imports {
+    my ($raw) = @_;
+    my %imports;
+    my %path_to_aliases;
+
+    while ($raw =~ /import\s+"([^"]+)"/g) {
+        my $path = $1;
+        my $alias = basename($path);
+        $alias =~ s/-//g;
+        $imports{$alias} = $path;
+        push @{ $path_to_aliases{$path} }, $alias;
+    }
+    while ($raw =~ /import\s*\((.*?)\)/sg) {
+        my $block = $1;
+        for my $line (split /\n/, $block) {
+            $line =~ s/\/\/.*$//;
+            next if $line =~ /^\s*$/;
+            if ($line =~ /^\s*([\w\.]+)\s+"([^"]+)"/) {
+                my ($alias, $path) = ($1, $2);
+                $imports{$alias} = $path;
+                push @{ $path_to_aliases{$path} }, $alias;
+            } elsif ($line =~ /^\s*"([^"]+)"/) {
+                my $path = $1;
+                my $alias = basename($path);
+                $alias =~ s/-//g;
+                $imports{$alias} = $path;
+                push @{ $path_to_aliases{$path} }, $alias;
+            }
+        }
+    }
+    return (\%imports, \%path_to_aliases);
+}
+
+sub find_enclosing_func {
+    my ($lines, $line_idx) = @_;
+    for (my $i = $line_idx; $i >= 0; $i--) {
+        my $l = $lines[$i];
+        if ($l =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
+            my ($recv, $name) = ($1, $2);
