for my $file (@internal_files) {
    open my $fh, '<', $file or next;
    local $/;
    my $raw = <$fh>;
    close $fh;

    my $pkg = ($raw =~ /^package\s+(\w+)/m) ? $1 : 'unknown';
    my $pkg_path = pkg_path_from_file($file);
    my @lines = split /\n/, $raw;
    for my $ln (0 .. $#lines) {
        my $line = $lines[$ln];
        next unless $line =~ /^\s*func\s+/;
        my ($recv, $name);
        if ($line =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
            ($recv, $name) = ($1, $2);
            $recv =~ s/^\s+|\s+$//g;
            if ($recv =~ /\*\s*([\w\.]+)\s*$/) { $recv = $1; }
            elsif ($recv =~ /([\w\.]+)\s*$/) { $recv = $1; }
        } elsif ($line =~ /^\s*func\s+(\w+)\s*[\(<]/) {
            ($name, $recv) = ($1, '');
        } else { next; }
        my $id = $recv ne '' ? "$file:($recv).$name" : "$file:$name";
        add_decl({
            name => $name, recv => $recv, pkg => $pkg, pkg_path => $pkg_path,
            file => $file, line => $ln + 1, id => $id,
        });
    }
}

# Ambiguous method/function names across internal/
my %ambiguous_names;
for my $name (keys %name_to_keys) {
    $ambiguous_names{$name} = 1 if scalar(@{ $name_to_keys{$name} }) > 1;
}

sub parse_imports {
    my ($raw) = @_;
    my %imports;
    my %path_to_aliases;
    while ($raw =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        my $alias = basename($path); $alias =~ s/-//g;
        $imports{$alias} = $path;
        push @{ $path_to_aliases{$path} }, $alias;
    }
    while ($raw =~ /import\s*\((.*?)\)/sg) {
        for my $line (split /\n/, $1) {
            $line =~ s/\/\/.*$//;
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*([\w\.]+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
                push @{ $path_to_aliases{$2} }, $1;
            } elsif ($line =~ /^\s*"([^"]+)"/) {
                my $path = $1;
                my $alias = basename($path); $alias =~ s/-//g;
                $imports{$alias} = $path;
                push @{ $path_to_aliases{$path} }, $alias;
            }
        }
    }
    return (\%imports, \%path_to_aliases);
}

sub find_enclosing_func {
    my ($lines, $line_idx) = @_;
    for (my $i = $line_idx; $i >= 0; $i--) {
        my $l = $lines[$i];
        if ($l =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
            my ($recv, $name) = ($1, $2);
            $recv =~ s/^\s+|\s+$//g;
            if ($recv =~ /\*\s*([\w\.]+)\s*$/) { $recv = $1; }
            elsif ($recv =~ /([\w\.]+)\s*$/) { $recv = $1; }
            return $recv ? "$file:($recv).$name" : "$file:$name";
        }
        if ($l =~ /^\s*func\s+(\w+)\s*[\(<]/) { return "$file:$1"; }
    }
    return "$file:<toplevel>";
}

my %counts_all;
my %counts_prod;
my %sites_all;
my %sites_prod;
my %caller_funcs_all;
my %caller_funcs_prod;
my %evidence;

sub record_call {
    my ($key, $file, $line_no, $snippet, $is_test, $caller) = @_;
    $counts_all{$key}++;
    $sites_all{$key}{"$file:$line_no"} = 1;
    $caller_funcs_all{$key}{$caller} = 1;
    if (!$is_test) {
        $counts_prod{$key}++;
        $sites_prod{$key}{"$file:$line_no"} = 1;
        $caller_funcs_prod{$key}{$caller} = 1;
    }
    push @{ $evidence{$key} }, "$file:$line_no: $snippet"
        if (!exists $evidence{$key} || scalar(@{ $evidence{$key} }) < 8);
}

my @all_go = split /\n/, `find '$REPO' -name '*.go' -type f 2>/dev/null`;
chomp @all_go;

for my $file (@all_go) {
    open my $fh, '<', $file or next;
    local $/;
    my $raw = <$fh>;
    close $fh;

    my $is_test = is_test_file($file);
    my $stripped = strip_go_source($raw);
    my ($imports, $path_aliases) = parse_imports($raw);
    my $caller_pkg_path = pkg_path_from_file($file);
    my @raw_lines = split /\n/, $raw;
    my @stripped_lines = split /\n/, $stripped;

    my %aliases_for_pkg;
    for my $key (keys %decls) {
        my $pp = $decls{$key}{pkg_path};
        my %seen;
        my @aliases;
        if ($caller_pkg_path eq $pp) { push @aliases, ''; $seen{''}=1; }
        if ($path_aliases->{$pp}) {
            for my $a (@{ $path_aliases->{$pp} }) {
                next if $seen{$a}++; push @aliases, $a;
            }
        }
        for my $alias (keys %$imports) {
            next unless $imports->{$alias} eq $pp;
            next if $seen{$alias}++; push @aliases, $alias;
        }
        $aliases_for_pkg{$key} = \@aliases if @aliases;
    }

    for my $ln (0 .. $#stripped_lines) {
        my $line = $stripped_lines[$ln];
        my $raw_line = $raw_lines[$ln] // '';
        next if $line =~ /^\s*func\s+/;
        my $caller = find_enclosing_func(\@stripped_lines, $ln);

        for my $key (keys %decls) {
            next unless $aliases_for_pkg{$key};
            my $d = $decls{$key};
            my ($name, $recv) = ($d->{name}, $d->{recv});

            # Skip ambiguous unqualified function names when caller doesn't share package
            if ($recv eq '' && $ambiguous_names{$name}) {
                my $has_unqual = grep { $_ eq '' } @{ $aliases_for_pkg{$key} };
                # still allow package-qualified only for ambiguous
            }

            for my $alias (@{ $aliases_for_pkg{$key} }) {
                if ($recv eq '') {
                    next if $ambiguous_names{$name} && $alias eq '' && $caller_pkg_path ne $d->{pkg_path};
                    if ($alias eq '') {
                        while ($line =~ /\b\Q$name\E\s*\(/g) {
                            my $pos = pos($line) - length($name) - 1;
                            next if $pos > 0 && substr($line, $pos - 1, 1) eq '.';
                            record_call($key, $file, $ln+1, substr($raw_line,0,120), $is_test, $caller);
                        }
                    } else {
                        while ($line =~ /\b\Q$alias\E\.\Q$name\E\s*\(/g) {
                            record_call($key, $file, $ln+1, substr($raw_line,0,120), $is_test, $caller);
                        }
                    }
                } else {
                    # Methods: only count in files that import/are in declaring package
                    # AND for ambiguous method names, require type hint on same line if possible
                    next if $ambiguous_names{$name} && $caller_pkg_path ne $d->{pkg_path}
                        && !( $line =~ /\b\Q$recv\E/ || $line =~ /\*\Q$recv\E/ );
                    while ($line =~ /\.\Q$name\E\s*\(/g) {
                        record_call($key, $file, $ln+1, substr($raw_line,0,120), $is_test, $caller);
                    }
                }
            }
        }
    }
}

my @ranked_all = sort { ($counts_all{$b}//0) <=> ($counts_all{$a}//0) || $a cmp $b } keys %decls;
my @ranked_prod = sort { ($counts_prod{$b}//0) <=> ($counts_prod{$a}//0) || $a cmp $b } keys %decls;

sub print_ranked {
    my ($title, $ranked, $counts, $sites, $callers) = @_;
    print "\n=== $title ===\n";
    my $n = 0;
    for my $key (@$ranked) {
        last if $n >= 20;
        my $d = $decls{$key};
        my $c = $counts->{$key} // 0;
        next if $c == 0 && $n >= 12;
        printf "%3d  %4d call sites  %3d distinct file:line  %3d caller funcs  %s\n",
            $n+1, $c, scalar(keys %{$sites->{$key}//{}}), scalar(keys %{$callers->{$key}//{}}), $d->{id};
        print "      decl $d->{file}:$d->{line}\n";
        if ($c && $evidence{$key}) {
            for my $ev (@{ $evidence{$key} }) { print "      -> $ev\n"; }
        }
        $n++;
    }
}

print "Internal declarations: ", scalar(keys %decls), "\n";
print "Ambiguous names (multiple internal decls): ", scalar(keys %ambiguous_names), "\n";
print "Go files scanned: ", scalar(@all_go), "\n";
print_ranked('ALL files', \@ranked_all, \%counts_all, \%sites_all, \%caller_funcs_all);
print_ranked('PRODUCTION only', \@ranked_prod, \%counts_prod, \%sites_prod, \%caller_funcs_prod);

for my ($label, $w) (['ALL', $ranked_all[0]], ['PROD', $ranked_prod[0]]) {
    my $d = $decls{$w};
    my $c = ($label eq 'ALL' ? $counts_all : $counts_prod)->{$w} // 0;
    print "\nWINNER $label: $d->{id} @ $d->{file}:$d->{line} = $c\n";
}

