#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

sub strip_go_source {
    my ($src) = @_;
    my $out = '';
    my $i = 0;
    my $len = length($src);
    while ($i < $len) {
        my $c = substr($src, $i, 1);
        if ($c eq '/' && $i + 1 < $len) {
            my $n = substr($src, $i + 1, 1);
            if ($n eq '/') {
                $i += 2;
                while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
                next;
            }
            if ($n eq '*') {
                $i += 2;
                while ($i + 1 < $len && !(substr($src, $i, 1) eq '*' && substr($src, $i + 1, 1) eq '/')) {
                    $i++;
                }
                $i += 2 if $i + 1 < $len;
                next;
            }
        }
        if ($c eq '"' || $c eq '`') {
            my $quote = $c;
            $out .= $c;
            $i++;
            while ($i < $len) {
                my $ch = substr($src, $i, 1);
                $out .= $ch;
                $i++;
                if ($ch eq '\\' && $i < $len) {
                    $out .= substr($src, $i, 1);
                    $i++;
                    next;
                }
                last if $ch eq $quote;
            }
            next;
        }
        if ($c eq "'" && $i + 2 < $len) {
            $out .= substr($src, $i, 3);
            $i += 3;
            next;
        }
        $out .= $c;
        $i++;
    }
    return $out;
}

sub is_test_file {
    my ($path) = @_;
    return $path =~ /_test\.go$/;
}

sub pkg_path_from_file {
    my ($file) = @_;
    my $dir = dirname($file);
    $dir =~ s/^\Q$REPO\E\/?//;
    return $dir eq '' ? $MODULE : "$MODULE/$dir";
}

my %decls;
my @decl_order;

sub decl_key {
    my ($pkg_path, $recv, $name) = @_;
    $recv //= '';
    return "$pkg_path|$recv|$name";
}

sub parse_internal_decls {
    find({
        wanted => sub {
            return unless $_ =~ /\.go$/;
            return unless $File::Find::name =~ m{^\Q$REPO\E/internal/};
            my $file = $File::Find::name;
            open my $fh, '<', $file or return;
            local $/;
            my $raw = <$fh>;
            close $fh;

            my $pkg = 'unknown';
            if ($raw =~ /^package\s+(\w+)/m) {
                $pkg = $1;
            }
            my $pkg_path = pkg_path_from_file($file);
            my @lines = split /\n/, $raw;
            for my $ln (0 .. $#lines) {
                my $line = $lines[$ln];
                next unless $line =~ /^\s*func\s+/;
                my ($recv, $name);
                if ($line =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
                    ($recv, $name) = ($1, $2);
                    $recv =~ s/^\s+|\s+$//g;
                    if ($recv =~ /\*\s*([\w\.]+)\s*$/) {
                        $recv = $1;
                    } elsif ($recv =~ /([\w\.]+)\s*$/) {
                        $recv = $1;
                    }
                } elsif ($line =~ /^\s*func\s+(\w+)\s*[\(<]/) {
                    $name = $1;
                    $recv = '';
                } else {
                    next;
                }
                my $key = decl_key($pkg_path, $recv, $name);
                my $id = "$file:$name";
                $id = "$file:($recv).$name" if $recv ne '';
                $decls{$key} = {
                    name     => $name,
                    recv     => $recv,
                    pkg      => $pkg,
                    pkg_path => $pkg_path,
                    file     => $file,
                    line     => $ln + 1,
                    id       => $id,
                };
                push @decl_order, $key;
            }
        },
        no_chdir => 1,
    }, "$REPO/internal");
}

sub parse_imports {
    my ($raw) = @_;
    my %imports;
    my %path_to_aliases;

    while ($raw =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        my $alias = basename($path);
        $alias =~ s/-//g;
        $imports{$alias} = $path;
        push @{ $path_to_aliases{$path} }, $alias;
    }
    while ($raw =~ /import\s*\((.*?)\)/sg) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/\/\/.*$//;
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*([\w\.]+)\s+"([^"]+)"/) {
                my ($alias, $path) = ($1, $2);
                $imports{$alias} = $path;
                push @{ $path_to_aliases{$path} }, $alias;
            } elsif ($line =~ /^\s*"([^"]+)"/) {
                my $path = $1;
                my $alias = basename($path);
                $alias =~ s/-//g;
                $imports{$alias} = $path;
                push @{ $path_to_aliases{$path} }, $alias;
            }
        }
    }
    return (\%imports, \%path_to_aliases);
}

sub find_enclosing_func {
    my ($lines, $line_idx) = @_;
    for (my $i = $line_idx; $i >= 0; $i--) {
        my $l = $lines[$i];
        if ($l =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
            my ($recv, $name) = ($1, $2);
            $recv =~ s/^\s+|\s+$//g;
            if ($recv =~ /\*\s*([\w\.]+)\s*$/) { $recv = $1; }
            elsif ($recv =~ /([\w\.]+)\s*$/) { $recv = $1; }
            return $recv ? "($recv).$name" : $name;
        }
        if ($l =~ /^\s*func\s+(\w+)\s*[\(<]/) {
            return $1;
        }
    }
    return '<toplevel>';
}

my %counts_all;
my %counts_prod;
my %callers_all;
my %callers_prod;
my %distinct_caller_funcs_all;
my %distinct_caller_funcs_prod;
my %evidence;

sub record_call {
    my ($key, $file, $line_no, $snippet, $is_test, $caller_func) = @_;
    $counts_all{$key}++;
    $callers_all{$key}{"$file:$line_no"} = 1;
    $distinct_caller_funcs_all{$key}{"$file:$caller_func"} = 1;
    if (!$is_test) {
        $counts_prod{$key}++;
        $callers_prod{$key}{"$file:$line_no"} = 1;
        $distinct_caller_funcs_prod{$key}{"$file:$caller_func"} = 1;
    }
    if (!exists $evidence{$key} || scalar(@{ $evidence{$key} }) < 8) {
        push @{ $evidence{$key} }, "$file:$line_no: $snippet";
    }
}

sub count_calls_in_file {
    my ($file) = @_;
    open my $fh, '<', $file or return;
    local $/;
    my $raw = <$fh>;
    close $fh;

    my $is_test = is_test_file($file);
    my $stripped = strip_go_source($raw);
    my ($imports, $path_aliases) = parse_imports($raw);
    my $caller_pkg_path = pkg_path_from_file($file);

    my @raw_lines = split /\n/, $raw;
    my @stripped_lines = split /\n/, $stripped;

    my %aliases_for_pkg;
    for my $key (keys %decls) {
        my $d = $decls{$key};
        my $pp = $d->{pkg_path};
        my %seen;
        my @aliases;
        if ($caller_pkg_path eq $pp) {
            push @aliases, '';
            $seen{''} = 1;
        }
        if (exists $path_aliases->{$pp}) {
            for my $a (@{ $path_aliases->{$pp} }) {
                next if $seen{$a}++;
                push @aliases, $a;
            }
        }
        for my $alias (keys %$imports) {
            next unless $imports->{$alias} eq $pp;
            next if $seen{$alias}++;
            push @aliases, $alias;
        }
        $aliases_for_pkg{$key} = \@aliases if @aliases;
    }

    for my $ln (0 .. $#stripped_lines) {
        my $line = $stripped_lines[$ln];
        my $raw_line = $raw_lines[$ln] // '';
        next if $line =~ /^\s*func\s+/;

        my $caller_func = find_enclosing_func(\@stripped_lines, $ln);

        for my $key (keys %decls) {
            next unless exists $aliases_for_pkg{$key};
            my $d = $decls{$key};
            my $name = $d->{name};
            my $recv = $d->{recv};

            for my $alias (@{ $aliases_for_pkg{$key} }) {
                if ($recv eq '') {
                    if ($alias eq '') {
                        while ($line =~ /\b\Q$name\E\s*\(/g) {
                            my $pos = pos($line) - length($name) - 1;
                            my $before = $pos > 0 ? substr($line, $pos - 1, 1) : '';
                            next if $before eq '.';
                            record_call($key, $file, $ln + 1, substr($raw_line, 0, 120), $is_test, $caller_func);
                        }
                    } else {
                        while ($line =~ /\b\Q$alias\E\.\Q$name\E\s*\(/g) {
                            record_call($key, $file, $ln + 1, substr($raw_line, 0, 120), $is_test, $caller_func);
                        }
                    }
                } else {
                    while ($line =~ /\.\Q$name\E\s*\(/g) {
                        record_call($key, $file, $ln + 1, substr($raw_line, 0, 120), $is_test, $caller_func);
                    }
                }
            }
        }
    }
}

parse_internal_decls();

my @all_go;
find({
    wanted => sub {
        return unless $_ =~ /\.go$/;
        push @all_go, $File::Find::name;
    },
    no_chdir => 1,
}, $REPO);

for my $file (@all_go) {
    count_calls_in_file($file);
}

my @ranked_all = sort {
    ($counts_all{$b} // 0) <=> ($counts_all{$a} // 0) || $a cmp $b
} keys %decls;

my @ranked_prod = sort {
    ($counts_prod{$b} // 0) <=> ($counts_prod{$a} // 0) || $a cmp $b
} keys %decls;

sub print_ranked {
    my ($title, $ranked, $counts, $callers, $caller_funcs) = @_;
    print "\n=== $title ===\n";
    my $n = 0;
    for my $key (@$ranked) {
        last if $n >= 20;
        my $d = $decls{$key};
        my $c = $counts->{$key} // 0;
        next if $c == 0 && $n >= 12;
        my $site_count = scalar keys %{ $callers->{$key} // {} };
        my $func_count = scalar keys %{ $caller_funcs->{$key} // {} };
        print sprintf("%3d  %4d syntactic call sites  %3d distinct file:line sites  %3d distinct caller funcs  %s\n",
            $n + 1, $c, $site_count, $func_count, $d->{id});
        print "      decl: $d->{file}:$d->{line}  pkg=$d->{pkg_path}\n";
        if ($c > 0 && exists $evidence{$key}) {
            for my $ev (@{ $evidence{$key} }) {
                print "      -> $ev\n";
            }
        }
        $n++;
    }
}

print "Fan-in analysis for internal/ declarations\n";
print "Methodology: distinct syntactic call sites per matching line occurrence\n";
print "Total internal declarations: " . scalar(keys %decls) . "\n";
print "Total Go files scanned: " . scalar(@all_go) . "\n";

print_ranked('ALL Go files', \@ranked_all, \%counts_all, \%callers_all, \%distinct_caller_funcs_all);
print_ranked('PRODUCTION only (exclude *_test.go callers)', \@ranked_prod, \%counts_prod, \%callers_prod, \%distinct_caller_funcs_prod);

my $win_all = $ranked_all[0];
my $win_prod = $ranked_prod[0];
my $wa = $decls{$win_all};
my $wp = $decls{$win_prod};
print "\n=== WINNER ALL ===\n";
print "$wa->{id} @ $wa->{file}:$wa->{line} => " . ($counts_all{$win_all} // 0) . "\n";
print "\n=== WINNER PROD ===\n";
print "$wp->{id} @ $wp->{file}:$wp->{line} => " . ($counts_prod{$win_prod} // 0) . "\n";

