    while ($i < $len) {
        my $c = substr($src, $i, 1);
        if ($c eq '/' && $i + 1 < $len) {
            my $n = substr($src, $i + 1, 1);
            if ($n eq '/') {
                $i += 2;
                while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
                next;
            }
            if ($n eq '*') {
                $i += 2;
                while ($i + 1 < $len && !(substr($src, $i, 1) eq '*' && substr($src, $i + 1, 1) eq '/')) {
                    $i++;
                }
                $i += 2 if $i + 1 < $len;
                next;
            }
        }
        if ($c eq '"' || $c eq '`') {
            my $quote = $c;
            $out .= $c;
            $i++;
            while ($i < $len) {
                my $ch = substr($src, $i, 1);
                $out .= $ch;
                $i++;
                if ($ch eq '\\' && $i < $len) {
                    $out .= substr($src, $i, 1);
                    $i++;
